ion"]="ACT II — SCENE 5: SAV'S WORST DAY",["start"]=2628.618,["end"]=2632.065,["text"]="That triggered a fight between Sav and me.",["bed"]="human",["gain"]=0.075,["decision"]="HUMAN: restrained felt-piano memory motif",["timing"]="provisional based on manuscript and guide; must snap to recorded voice"},{["cue_index"]=177,["sentence_index"]=2,["section"]="ACT II — SCENE 5: SAV'S WORST DAY",["start"]=2632.065,["end"]=2633.789,["text"]="We blocked each other.",["bed"]="human",["gain"]=0.068,["decision"]="RELATIONSHIP / HUMAN CONSEQUENCES: muted fragile cue",["timing"]="provisional based on manuscript and guide; must snap to recorded voice"},{["cue_index"]=178,["sentence_index"]=0,["section"]="ACT II — SCENE 5: SAV'S WORST DAY",["start"]=2634.088,["end"]=2635.383,["text"]="Sav was overwhelmed.",["bed"]="human",["gain"]=0.075,["decision"]="HUMAN: restrained felt-piano memory motif",["timing"]="provisional based on manuscript and guide; must snap to recorded voice"},{["cue_index"]=178,["sentence_index"]=1,["section"]="ACT II — SCENE 5: SAV'S WORST DAY",["start"]=2635.383,["end"]=2643.154,["text"]="She was crying and sending incoherent messages in a group chat with Angela and their friend Sara Beth.",["bed"]="human",["gain"]=0.075,["decision"]="HUMAN: restrained felt-piano memory motif",["timing"]="provisional based on manuscript and guide; must snap to recorded voice"},{["cue_index"]=178,["sentence_index"]=2,["section"]="ACT II — SCENE 5: SAV'S WORST DAY",["start"]=2643.154,["end"]=2647.04,["text"]="She also made alarming statements about ending her life.",["bed"]="human",["gain"]=0.068,["decision"]="RELATIONSHIP / HUMAN CONSEQUENCES: muted fragile cue",["timing"]="provisional based on manuscript and guide; must snap to recorded voice"},{["cue_index"]=179,["sentence_index"]=0,["section"]="ACT II — SCENE 5: SAV'S WORST DAY",["start"]=2647.34,["end"]=2654.862,["text"]="Sav has acknowledged that those words were serious and that she shouldn't have used them lightly.",["bed"